                    "status": n.get("status") or "supposed",
                    "sources": [str(s)[:80] for s in n.get("sources") or []][:8],
                }
                if hid in by_id:
                    by_id[hid].update(note)
                else:
                    st.hypotheses.append(note)
                    by_id[hid] = note
            return {"your_notes": st.hypotheses}

